--
-- Структура таблицы `order_orders`
--

CREATE TABLE `order_orders` (
  `id` int NOT NULL,
  `public_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tenant_id` int DEFAULT '1',
  `store_id` int NOT NULL DEFAULT '1',
  `customer_id` int DEFAULT NULL,
  `customer_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `customer_phone` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `promo_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `delivery_address_id` int DEFAULT NULL,
  `pickup_store_id` int DEFAULT NULL COMMENT 'ID точки самовывоза (для takeaway/pickup)',
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cutlery_qty` int NOT NULL DEFAULT '0',
  `change_from` decimal(10,2) DEFAULT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `total_price` decimal(10,2) DEFAULT NULL,
  `delivery_cost` decimal(10,2) DEFAULT '0.00',
  `discount_amount` decimal(12,2) DEFAULT '0.00' COMMENT 'Общая сумма скидки',
  `discounts_json` json DEFAULT NULL COMMENT 'Детали примененных скидок',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `delivery_type_id` int DEFAULT NULL,
  `payment_id` int DEFAULT NULL,
  `time_option_id` int DEFAULT NULL,
  `status_id` int UNSIGNED DEFAULT NULL,
  `status_sort` int NOT NULL DEFAULT '0',
  `scheduled_at` datetime DEFAULT NULL,
  `created_via` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'web',
  `is_active` tinyint NOT NULL DEFAULT '1'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

